42: #include "errmsg.h"
43: #include <mysql/client_plugin.h>
44: 
45: #ifndef WIN32
46: #include <dlfcn.h>
47: #endif
48: 
49: const char *disabled_plugins= "@PLUGINS_DISABLED@";
50: 
51: struct st_client_plugin_int {
52:   struct st_client_plugin_int *next;
53:   void   *dlhandle;
54:   struct st_mysql_client_plugin *plugin;
55: };
56: 
57: static my_bool initialized= 0;
58: static MA_MEM_ROOT mem_root;
59: 
60: static uint valid_plugins[][2]= {
61:   {MYSQL_CLIENT_AUTHENTICATION_PLUGIN, MYSQL_CLIENT_AUTHENTICATION_PLUGIN_INTERFACE_VERSION},
62:   {MARIADB_CLIENT_PVIO_PLUGIN, MARIADB_CLIENT_PVIO_PLUGIN_INTERFACE_VERSION},
63:   {MARIADB_CLIENT_TRACE_PLUGIN, MARIADB_CLIENT_TRACE_PLUGIN_INTERFACE_VERSION},
64:   {MARIADB_CLIENT_REMOTEIO_PLUGIN, MARIADB_CLIENT_REMOTEIO_PLUGIN_INTERFACE_VERSION},
65:   {MARIADB_CLIENT_CONNECTION_PLUGIN, MARIADB_CLIENT_CONNECTION_PLUGIN_INTERFACE_VERSION},
66:   {MARIADB_CLIENT_COMPRESSION_PLUGIN, MARIADB_CLIENT_COMPRESSION_PLUGIN_INTERFACE_VERSION},
67:   {0, 0}
68: };
69: 
70: /*
71:   Loaded plugins are stored in a linked list.
72:   The list is append-only, the elements are added to the head (like in a stack).
73:   The elements are added under a mutex, but the list can be read and traversed
74:   without any mutex because once an element is added to the list, it stays
75:   there. The main purpose of a mutex is to prevent two threads from
76:   loading the same plugin twice in parallel.
77: */
78: 
79: 
80: struct st_client_plugin_int *plugin_list[MYSQL_CLIENT_MAX_PLUGINS + MARIADB_CLIENT_MAX_PLUGINS];
81: #ifdef THREAD
82: static pthread_mutex_t LOCK_load_client_plugin;
83: #endif
84: 
85: @EXTERNAL_PLUGINS@
86: 
87: struct st_mysql_client_plugin *mysql_client_builtins[]=
88: {
89:   @BUILTIN_PLUGINS@
90:   0
91: };
