94: static int is_not_initialized(MYSQL *mysql, const char *name)
95: {
96:   if (initialized)
97:     return 0;
98: 
99:   my_set_error(mysql, CR_AUTH_PLUGIN_CANNOT_LOAD,
100:                SQLSTATE_UNKNOWN, ER(CR_AUTH_PLUGIN_CANNOT_LOAD),
101:                name, "not initialized");
102:   return 1;
103: }
104: 
105: static int get_plugin_nr(uint type)
106: {
107:   uint i= 0;
108:   for(; valid_plugins[i][1]; i++)
109:     if (valid_plugins[i][0] == type)
110:       return i;
111:   return -1;
112: }
113: 
114: static const char *check_plugin_version(struct st_mysql_client_plugin *plugin, unsigned int version)
115: {
116:   if (plugin->interface_version >> 8 != version >> 8)
117:     return "Incompatible client plugin interface";
118:   return 0;
119: }
120: 
121: /**
122:   finds a plugin in the list
123: 
124:   @param name   plugin name to search for
125:   @param type   plugin type
126: 
127:   @note this does NOT necessarily need a mutex, take care!
128:   
129:   @retval a pointer to a found plugin or 0
130: */
131: static struct st_mysql_client_plugin *find_plugin(const char *name, int type)
132: {
133:   struct st_client_plugin_int *p;
134:   int plugin_nr= get_plugin_nr(type);
135: 
136:   DBUG_ASSERT(initialized);
137:   if (plugin_nr == -1)
138:     return 0;
139: 
140:   if (!name)
141:   {
142:     if (plugin_list[plugin_nr])
143:       return plugin_list[plugin_nr]->plugin;
144:     return NULL;
145:   }
146: 
147:   for (p= plugin_list[plugin_nr]; p; p= p->next)
148:   {
149:     if (strcmp(p->plugin->name, name) == 0)
150:       return p->plugin;
151:   }
152:   return NULL;
153: }
154: 
